const {vec, smat} = NMath;
const {vertices, faces} = await IO.loadMesh("/assets/bob.obj");

const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    const scaled = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};

const originalPts = normalizeVectors(vertices.map(vertex => vec(...vertex)));
let pts = originalPts.slice();
const n = pts.length;
const dim = 3;

// the neighborhoods are fixed, only the vertex positions change
const graph = Graph.knn(pts, 4, (x, y) => x.sub(y).length());
const normalGraph = Graph.knn(pts, 8, (x, y) => x.sub(y).length());
const neighbors = pts.map((_, i) => normalGraph.getNeighbors(i).map(Number));
const sigma = 0.05;
const maxDegree = Math.max(1, ...Object.keys(graph.vertices).map(id => graph.getNeighbors(id).length));
const maxAlpha = 0.9 / maxDegree;
let alpha = Math.min(0.05, maxAlpha); // Laplacian smoothing
let lambdaRepel = 0.01; // largest repulsion displacement per step
let ite = 1; // Default iterations per click

const points = pts.map(point => point.toArray());
const pointPlot = IO.plotPointCloud(points, {color: [0.5, 0.5, 0.5]});
const rasterPlot = IO.raster(points, faces, {color: [0.5, 0.5, 0.5]});

// the normal is the eigenvector with the lowest eigenvalue of the neighborhood covariance
const estimateNormals = positions => positions.map((_, i) => {
    const neighborhood = [i, ...neighbors[i]].map(j => positions[j].toArray());
    const {components} = PCA.new(neighborhood, dim);
    return components[components.length - 1];
});

// angular synchronization: the leading eigenvector of W_ij = n_i . n_j gives the sign of each normal
const synchronize = field => {
    // the shift makes the matrix positive semidefinite, so the power method finds the largest eigenvalue
    const shift = Math.max(...neighbors.map(list => list.length));
    const builder = smat.builder(n, n);
    for (let i = 0; i < n; i++) {
        builder.set(i, i, shift);
        neighbors[i].forEach(j => builder.set(i, j, field[i].dot(field[j])));
    }
    const {eigenvectors} = builder.build().eigen({k: 1, maxIterations: 2000, tolerance: 1e-4});
    const signs = eigenvectors[0].toArray().map(x => (x < 0 ? -1 : 1));
    const flipped = field.map((normal, i) => normal.scale(signs[i]));
    // the global sign is free, so make most normals point away from the center of the cloud
    const outward = flipped.reduce((sum, normal, i) => sum + normal.dot(pts[i]), 0);
    return outward < 0 ? flipped.map(normal => normal.scale(-1)) : flipped;
};

let normals = [];

// points move little per step, so the previous oriented normals are a reference for the new signs
const updateNormals = () => {
    const estimated = estimateNormals(pts);
    normals = estimated.map((normal, i) => (normal.dot(normals[i]) < 0 ? normal.scale(-1) : normal));
};

const updatePlot = () => {
    const newPoints = pts.map(point => point.toArray());
    pointPlot.update(newPoints, {color: [0.5, 0.5, 0.5]});
    rasterPlot.update(newPoints, faces, {color: [0.5, 0.5, 0.5]});
    pointPlot.render();
    rasterPlot.render();
};

// tangent-point energy E = sum_ij A_i A_j (|d . n_i|^2 + |d . n_j|^2) / |d|^4, with d = x_i - x_j, i.e. the integral of 1/R^2
// it vanishes for points on a common tangent plane and blows up for close points that are not tangent, so no threshold is needed
// A_i is the area of the patch around point i, so that uneven sampling does not change the energy
// the force is -grad E, with the normals and areas held fixed; all pairs are used, O(n^2) per step
const smoothingPasses = 2;
const flatten = vectors => {
    const flat = new Float64Array(n * dim);
    for (let i = 0; i < n; i++) for (let d = 0; d < dim; d++) flat[i * dim + d] = vectors[i].components[d];
    return flat;
};

// patch area from the radius of the neighborhood, normalized to mean 1
const patchAreas = () => {
    const areas = pts.map((point, i) => Math.max(...neighbors[i].map(j => point.sub(pts[j]).squareLength())));
    const mean = areas.reduce((sum, a) => sum + a, 0) / n;
    return Float64Array.from(areas, a => a / mean);
};

const adjacency = neighbors.map(list => new Set(list));

// forces is optional, when given it receives -grad E
const tangentPointEnergy = (p, nn, areas, forces) => {
    let energy = 0;
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            if (adjacency[i].has(j) || adjacency[j].has(i)) continue; // the normals are fitted on the local patch
            const dx = p[i * 3] - p[j * 3];
            const dy = p[i * 3 + 1] - p[j * 3 + 1];
            const dz = p[i * 3 + 2] - p[j * 3 + 2];
            const distSq = dx * dx + dy * dy + dz * dz + 1e-9;
            const aI = dx * nn[i * 3] + dy * nn[i * 3 + 1] + dz * nn[i * 3 + 2];
            const aJ = dx * nn[j * 3] + dy * nn[j * 3 + 1] + dz * nn[j * 3 + 2];
            const weight = areas[i] * areas[j];
            const invDist4 = weight / (distSq * distSq);
            energy += (aI * aI + aJ * aJ) * invDist4;
            if (!forces) continue;
            const radial = 4 * (aI * aI + aJ * aJ) * invDist4 / distSq;
            // g = dE/dd, the force is -g on i and +g on j
            const gx = 2 * (aI * nn[i * 3] + aJ * nn[j * 3]) * invDist4 - radial * dx;
            const gy = 2 * (aI * nn[i * 3 + 1] + aJ * nn[j * 3 + 1]) * invDist4 - radial * dy;
            const gz = 2 * (aI * nn[i * 3 + 2] + aJ * nn[j * 3 + 2]) * invDist4 - radial * dz;
            forces[i * 3] -= gx;
            forces[i * 3 + 1] -= gy;
            forces[i * 3 + 2] -= gz;
            forces[j * 3] += gx;
            forces[j * 3 + 1] += gy;
            forces[j * 3 + 2] += gz;
        }
    }
    return energy;
};

// the raw gradient is dominated by high frequencies, averaging over the neighbors is a cheap smooth descent direction
const smoothForces = forces => {
    let current = forces;
    for (let pass = 0; pass < smoothingPasses; pass++) {
        const next = new Float64Array(n * dim);
        for (let i = 0; i < n; i++) {
            for (let d = 0; d < dim; d++) {
                let sum = current[i * dim + d];
                for (const j of neighbors[i]) sum += current[j * dim + d];
                next[i * dim + d] = sum / (neighbors[i].length + 1);
            }
        }
        current = next;
    }
    return current;
};

const takeFlowStep = () => {
    // 1. Estimate oriented normals, patch areas and the smoothed tangent-point forces
    updateNormals();
    const areas = patchAreas();
    const p = flatten(pts);
    const nn = flatten(normals);
    const rawForces = new Float64Array(n * dim);
    const energy = tangentPointEnergy(p, nn, areas, rawForces);
    const forces = smoothForces(rawForces);
    // the energy gradient spans many orders of magnitude, so the step size is the largest displacement
    let maxForce = 0;
    for (let i = 0; i < n; i++) {
        maxForce = Math.max(maxForce, Math.hypot(forces[i * dim], forces[i * dim + 1], forces[i * dim + 2]));
    }

    // 2. Backtracking: halve the repulsion step until the energy decreases
    let step = maxForce > 0 ? lambdaRepel / maxForce : 0;
    const trial = new Float64Array(n * dim);
    for (let attempt = 0; attempt < 6 && step > 0; attempt++) {
        for (let k = 0; k < n * dim; k++) trial[k] = p[k] + forces[k] * step;
        if (tangentPointEnergy(trial, nn, areas) < energy) break;
        step *= 0.5;
        if (attempt === 5) step = 0;
    }

    // 3. Dynamic Laplacian smoothing of the coordinates
    for (let i = 0; i < n; i++) graph.getVertex(i).vertex = pts[i];
    const laplacian = graph.laplacian((i, j) => Math.exp(-i.vertex.sub(j.vertex).squareLength() / sigma));
    const smoothing = Array(dim).fill(0).map((_, d) =>
        laplacian.prodVec(vec(...pts.map(point => point.components[d]))).scale(alpha)
    );

    // 4. Repulsion plus Laplacian smoothing
    const flowedPts = pts.map((point, i) => point
        .add(vec(forces[i * dim], forces[i * dim + 1], forces[i * dim + 2]).scale(step))
        .sub(vec(...smoothing.map(coordinate => coordinate.components[i]))));

    // 5. Center to origin
    const mean = flowedPts.reduce((sum, point) => sum.add(point), vec.zero(dim)).scale(1 / n);
    pts = flowedPts.map(point => point.sub(mean));
};

// Run multiple iterations per click
const runIntegration = () => {
    for (let i = 0; i < ite; i++) {
        takeFlowStep();
    }
    updatePlot();
};

const resetSimulation = () => {
    pts = originalPts.slice();
    normals = synchronize(estimateNormals(pts));
    updatePlot();
};

resetSimulation();

const ui = IO.UI(
    {type: "group", value: () => [
        {type: "canvas", value: () => pointPlot},
        {type: "canvas", value: () => rasterPlot},
    ]},
    {type: "group", value: () => [
        {type: "button", value: () => ({title: "Reset", onClick: resetSimulation})},
        {type: "button", value: () => ({title: "Integrate", onClick: runIntegration})},
    ]},
    {type: "slider", value: () => ({
        min: 0,
        max: maxAlpha,
        step: maxAlpha / 100,
        value: alpha,
        title: "Alpha:",
        onChange: value => { alpha = value; },
    })},
    {type: "slider", value: () => ({
        min: 0,
        max: 0.05,
        step: 0.001,
        value: lambdaRepel,
        title: "Repulsion step:",
        onChange: value => { lambdaRepel = value; },
    })},
    {type: "slider", value: () => ({
        min: 1,
        max: 100,
        step: 1,
        value: ite,
        title: "Iterations (ite):",
        onChange: value => { ite = Math.round(value); },
    })},
);
ui;
